window.LD=window.LD||{};window.LD["party/p1"]={"id":"p1","name":"Red Hammers","poss":"Red Hammers'","members":["h13","h14"],"leader":"h13","morale":99,"disposition":"predatory","motto":"Is there a party? We're the party.","banner":{"c1":"#e8823a","c2":"#c8323c","emblem":"hammer"},"loc":"thornmere_ruins","loc_name":"Thornmere Ruins","goal":{"text":"to earn 1,550 silver between them before the season ends","kind":"purse","done":null,"progress":"268 of 1,550 silver","missed":true,"crew":"Red Hammers","party":"p1"},"vows":[{"text":"to die rich","day":31,"state":"broken","ended":90,"through":false,"progress":"broken on day 30 of season 3","crew":"Red Hammers","party":"p1"}],"doing":"last seen delving into Thornmere Ruins","progress":null,"today":["Ate 4 rations.","Used up 7 torches."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":{"src":"book","id":"letters_in_the_fire","title":"Letters in the Fire","tone":"sad","meter":"4/4","bpm":74,"diff":3,"day":59,"night":"n142","n":12,"by":null,"lead":{"id":"h13","name":"Bramble","skill":0.623}},"renown":172,"season":{"wins":8,"bosses":0,"floors":7,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30},"career":{"wins":19,"bosses":0,"floors":18,"gold":0,"deaths":0,"fled":0,"pvp_wins":2,"pvp_losses":0,"renown":0,"days":90},"former":[],"fallen":[],"travel":null,"wagon":{"kind":"donkey_cart","name":"The Rattler","label":"donkey cart","seats":2,"haul":28,"comfort":1,"since":20,"desc":"Rattles. Gets there.","moves":true,"puller":{"kind":"donkey","name":"Hector","label":"donkey","colour":"brown","owner":"Ottoline"},"paid":[["Bramble",13],["Ottoline",11]]},"pace_gap":0,"rels":[{"party":"p3","score":-100},{"party":"p2","score":54},{"party":"p8","score":26},{"party":"p5","score":23},{"party":"p4","score":13},{"party":"p6","score":9}],"events":[{"id":"e26","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Bramble and Ottoline shake on it at The Honest Toll: they are now Red Hammers. (Predatory, by the look of them.)","heroes":["h13","h14"],"parties":["p1"],"loc":"carrbridge","wx":"storm"},{"id":"e491","day":13,"season":1,"sday":13,"kind":"pvp","imp":5,"text":"Red Hammers rout The Amber Sigil on the road between Ashfen and the Ashveil Crypts and walk off with 38 silver. The Amber Sigil comes for a toll and gets a fight instead.","heroes":["h11","h2","h16","h13","h14"],"parties":["p3","p1"],"loc":"ashfen","fight":"f42","losers":["h11","h2","h16"]},{"id":"e750","day":20,"season":1,"sday":20,"kind":"party_life","imp":1,"text":"By the third crossroads Bramble has stopped waiting and started complaining about the wait.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e753","day":20,"season":1,"sday":20,"kind":"wagon","imp":3,"text":"Red Hammers buy a donkey cart in Ashfen for 24 silver and hitch Ottoline's donkey, Hector, to it. Hector looks betrayed.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashfen"},{"id":"e841","day":22,"season":1,"sday":22,"kind":"delve","imp":1,"text":"Red Hammers descend into the Ashveil Crypts, partly explored (43%), map in hand.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e842","day":22,"season":1,"sday":22,"kind":"trap","imp":2,"text":"Bramble springs a coffin lid that falls in the coffin-makers' yard on the second floor of the Ashveil Crypts (concussion).","heroes":["h13"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e845","day":22,"season":1,"sday":22,"kind":"fight","imp":1,"text":"Three Skeletons stir in the choir loft on the second floor of the Ashveil Crypts, and Red Hammers see them off for good. The fight was over the moment Ottoline's Spark Jar landed on the skeleton. Loot: 8 bones, 2 crypt-caps.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f59","foes":["skeleton","skeleton","skeleton"],"where":"in the choir loft on the second floor of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-28,"wx":"fog"},{"id":"e846","day":22,"season":1,"sday":22,"kind":"delve_day","imp":1,"text":"A long day on the second floor of the Ashveil Crypts. Red Hammers come through two rooms, one door at a time: the coffin-makers' yard, the choir loft.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":1,"sprung":1,"trap_inj":1,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e847","day":22,"season":1,"sday":22,"kind":"talent","imp":2,"text":"Bramble drizzles wild honey over the porridge. Ottoline looks at Bramble as if Bramble invented joy.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","skill":"honey_finder","wx":"fog"},{"id":"e889","day":23,"season":1,"sday":23,"kind":"party_life","imp":3,"text":"Bramble has views about the second floor and expressed them sitting down. The views won, and Red Hammers turn for daylight.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","refusal":"h13","wx":"fog"},{"id":"e890","day":23,"season":1,"sday":23,"kind":"delve_done","imp":1,"text":"The Ashveil Crypts is behind Red Hammers now: 2 days down there, and the sky looks enormous. They took 2 rooms off the map's blank side, reached the second floor and turned back when one of them would go no further.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","days":2,"bottom":false,"rooms":[],"gold":0,"turn":"refused","wx":"fog"},{"id":"e891","day":23,"season":1,"sday":23,"kind":"talent","imp":1,"text":"Bramble watches the treeline for an hour without moving. Ottoline checks he is still breathing.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","skill":"still_as_a_heron","wx":"fog"},{"id":"e905","day":23,"season":1,"sday":23,"kind":"campfire","imp":1,"text":"The Ashveil Crypts is cold and the candles are short. Ottoline lends Bramble the warmer blanket without a word.","heroes":["h14","h13"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e933","day":24,"season":1,"sday":24,"kind":"meet","imp":2,"text":"Nobody offers to share a fire when The Amber Sigil and Red Hammers meet on the road between Ashfen and the Ashveil Crypts. Two small fires burn instead, twenty paces apart.","heroes":["h11","h2","h16","h13","h14"],"parties":["p3","p1"],"loc":"ashfen","wx":"fog"},{"id":"e934","day":24,"season":1,"sday":24,"kind":"ability","imp":2,"text":"An Ashfen tavern's painted sign is so faded nobody knows its name. Ottoline brings back 'The Laughing Trout' in gold light. Free bed, free breakfast, and a fine night's sleep.","heroes":["h14"],"parties":["p1"],"loc":"ashfen","skill":"glowing_signboard","sk":"The Glowing Signboard","rule":true,"wx":"fog"},{"id":"e964","day":25,"season":1,"sday":25,"kind":"bond","imp":2,"text":"The Amber Sigil and Red Hammers are rivals now, starting with Quill and Bramble. (5 heroes now hold grudges.)","heroes":["h11","h13","h14","h2","h16"],"parties":["p3","p1"],"bond":"rivals"},{"id":"e965","day":25,"season":1,"sday":25,"kind":"pvp","imp":5,"text":"Red Hammers force a surrender from The Amber Sigil at the mouth of the Ashveil Crypts and walk off with 7 silver. The Amber Sigil comes for a toll and gets a fight instead.","heroes":["h11","h2","h16","h13","h14"],"parties":["p3","p1"],"loc":"ashveil_crypts","fight":"f65","losers":["h11","h2","h16"],"wx":"fog"},{"id":"e983","day":26,"season":1,"sday":26,"kind":"delve","imp":1,"text":"Red Hammers descend into the Ashveil Crypts, partly explored (46%), map in hand.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e984","day":26,"season":1,"sday":26,"kind":"delve_day","imp":1,"text":"Red Hammers keep at the second floor of the Ashveil Crypts at a steady pace, one room deep in the day: the mourners' stair, a hundred worn steps.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":1,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e985","day":26,"season":1,"sday":26,"kind":"ability","imp":2,"text":"Bramble sits so still by the stream at the Ashveil Crypts that a heron lands beside them. They fish side by side. The heron gets a trout; Bramble gets a fox, and a pelt.","heroes":["h13"],"parties":["p1"],"loc":"ashveil_crypts","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true,"wx":"fog"},{"id":"e1032","day":27,"season":1,"sday":27,"kind":"party_life","imp":3,"text":"Bramble heard something in the wall on the second floor of the Ashveil Crypts. Nobody else did, but Red Hammers turn back all the same.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","refusal":"h13","wx":"fog"},{"id":"e1033","day":27,"season":1,"sday":27,"kind":"delve_done","imp":1,"text":"Red Hammers climb the last ladder after 2 days, and the sitting down happens at the top of it. They got down to the second floor, took 1 room off the map's blank side and turned back when one of them would go no further.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","days":2,"bottom":false,"rooms":[],"gold":0,"turn":"refused","wx":"fog"},{"id":"e1039","day":27,"season":1,"sday":27,"kind":"meet","imp":2,"text":"Red Hammers and The Amber Sigil need the same stream at the mouth of the Ashveil Crypts and take turns at it without a word, each side watching the other's hands.","heroes":["h13","h14","h11","h2","h16"],"parties":["p1","p3"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1045","day":27,"season":1,"sday":27,"kind":"talent","imp":2,"text":"Ottoline beats a dent out of Bramble's helmet on a flat rock. It fits better than it did new. Smith's Hands, the guild calls it.","heroes":["h14","h13"],"parties":["p1"],"loc":"ashveil_crypts","skill":"smith_hands","wx":"fog"},{"id":"e1073","day":28,"season":1,"sday":28,"kind":"talent","imp":1,"text":"Bramble trims a candle wick at the Ashfen tavern from across the room. The candle stays lit. The bets don't.","heroes":["h13"],"parties":["p1"],"loc":"ashfen","skill":"trick_shot","wx":"fog"},{"id":"e1085","day":28,"season":1,"sday":28,"kind":"ledger","imp":2,"text":"The week's trade: 7 packs emptied onto counters for 265 silver. Biggest haul: Ash, 89 silver in Carrbridge. Back up from the deep: Red Hammers (2 days in the Ashveil Crypts), Gilded Wall (7 days in Thornmere Ruins).","heroes":["h12","h13","h9"],"parties":["p1","p6"]},{"id":"e1130","day":29,"season":1,"sday":29,"kind":"campfire","imp":3,"text":"Ottoline wakes up to find Bramble has already made the tea. Exactly how Ottoline likes it.","heroes":["h14","h13"],"parties":["p1"],"loc":"ashfen","wx":"fog"},{"id":"e1163","day":30,"season":1,"sday":30,"kind":"talent","imp":1,"text":"Ottoline wins a hand at Carrbridge with a pair of queens. Both of cups. Nobody checks.","heroes":["h14"],"parties":["p1"],"loc":"carrbridge"},{"id":"e1178","day":30,"season":1,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and Red Hammers came up short: earn 900 silver between them before the season ends (446 of 900 silver).","heroes":["h13","h14"],"parties":["p1"]},{"id":"e1206","day":31,"season":2,"sday":1,"kind":"road","imp":3,"text":"Sir Aldous Puddle holds a hill-road bridge in the name of honour, and will let Bramble pass only after a friendly bout. Bramble agrees, politely.","heroes":["h13","h14"],"parties":["p1"],"road":"redcrag~veldrock","traveller":"aldous","road_rec":"r257"},{"id":"e1207","day":31,"season":2,"sday":1,"kind":"talent","imp":2,"text":"Bramble knocks a pine cone off a branch in the dark, by sound alone. Ottoline demands to see it again.","heroes":["h13","h14"],"parties":["p1"],"loc":"redcrag","skill":"trick_shot"},{"id":"e1208","day":31,"season":2,"sday":1,"kind":"ability","imp":2,"text":"Bramble watches a game trail near Redcrag Hills from dusk until the moon is up. One arrow, a fat buck, a pelt, and the quietest, happiest camp of the week.","heroes":["h13"],"parties":["p1"],"loc":"redcrag","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e1229","day":31,"season":2,"sday":1,"kind":"meet","imp":2,"text":"The Scarlet Gallopers and Red Hammers share a fire in Redcrag Hills. Rook and Bramble compare boots, then blisters, then regrets.","heroes":["h4","h15","h5","h13","h14"],"parties":["p5","p1"],"loc":"redcrag"},{"id":"e1236","day":31,"season":2,"sday":1,"kind":"campfire","imp":2,"text":"A month together in Red Hammers, and Bramble has finally learned Ottoline's middle name. There are three. It's a long story.","heroes":["h13","h14"],"parties":["p1"],"loc":"redcrag"},{"id":"e1247","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"\"We swear it,\" says every member of Red Hammers: to die rich. Witnessed, written down, and already being bet against.","heroes":["h13","h14"],"parties":["p1"]},{"id":"e1262","day":32,"season":2,"sday":2,"kind":"road","imp":3,"text":"Gerald the skeleton has come apart on the road. Ottoline helps the students find all the bits and tie Gerald back together with bootlaces.","heroes":["h14","h13"],"parties":["p1"],"road":"cragtooth_warren~redcrag","traveller":"truant_scholars","road_rec":"r271"},{"id":"e1263","day":32,"season":2,"sday":2,"kind":"talent","imp":1,"text":"Ottoline makes the campfire glow in Bramble's favourite colour. Somebody asks how. 'The Glowing Signboard,' says Ottoline.","heroes":["h14","h13"],"parties":["p1"],"loc":"cragtooth_warren","skill":"glowing_signboard"},{"id":"e1285","day":32,"season":2,"sday":2,"kind":"campfire","imp":1,"text":"Bramble and Ottoline race to the next milestone. Ottoline wins, and Bramble claims a technical foul.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e1292","day":33,"season":2,"sday":3,"kind":"delve","imp":1,"text":"Red Hammers descend into Cragtooth Warren, untouched (0%).","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e1293","day":33,"season":2,"sday":3,"kind":"fight","imp":2,"text":"Bramble hits hardest as Red Hammers defeat 3 Giant Bats and a Kobold in the bat roost on the first floor of Cragtooth Warren. The fight ended in a flash of Ottoline's Spark Jar. Patient Shot did more for this fight than the scoreboard shows. That was Bramble. Loot: 2 silver each, 1 fang, 2 bat wings.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","fight":"f76","foes":["giant_bat","kobold","giant_bat"],"where":"in the bat roost on the first floor of Cragtooth Warren","won":true,"close":false,"shape":"hero","reworded":-24},{"id":"e1295","day":33,"season":2,"sday":3,"kind":"gear","imp":1,"text":"In the bat roost on the first floor of Cragtooth Warren, Ottoline finds a Brass Lantern of the Long Night and puts it on. Of the Long Night: much braver (+5 nerve).","heroes":["h14"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e1296","day":33,"season":2,"sday":3,"kind":"fight","imp":1,"text":"Red Hammers defeat a Kobold and a Kobold Slinger in the sentry hole on the first floor of Cragtooth Warren. One Patient Shot from Bramble, and the kobold slinger stopped being a problem. Loot: 12 silver each, 4 ore, 1 trinket.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","fight":"f77","foes":["kobold","kobold_slinger"],"where":"in the sentry hole on the first floor of Cragtooth Warren","won":true,"close":false,"shape":"plain"},{"id":"e1297","day":33,"season":2,"sday":3,"kind":"delve_day","imp":1,"text":"The bat roost, the sentry hole, the prospectors' diggings: the day's work on the first floor of Cragtooth Warren for Red Hammers, taken without hurrying.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":3,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["great","common"],"fears":1,"wild":[]}},{"id":"e1316","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"Ottoline orders Bramble a cheap swill before Bramble even sits down. Remembering an order is how it starts.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e1339","day":34,"season":2,"sday":4,"kind":"artifact","imp":3,"text":"Bramble pockets a tin crown that tells its wearer who to distrust in Cragtooth Warren. Bramble feels stronger already.","heroes":["h13"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e1340","day":34,"season":2,"sday":4,"kind":"delve_day","imp":1,"text":"Torch by torch through the first floor of Cragtooth Warren, Red Hammers make it through three rooms, steadily: the first run, the spoil tip, the trap-maker's workshop.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":3,"empty":0,"size":2,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1371","day":35,"season":2,"sday":5,"kind":"delve_day","imp":1,"text":"It's the first floor of Cragtooth Warren today, and Red Hammers work through it one door at a time: one room (the kobold crawl).","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":1,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1372","day":35,"season":2,"sday":5,"kind":"ability","imp":2,"text":"A hare sits up in the grass at Cragtooth Warren, looks right at Bramble, and decides Bramble is a stump. Supper. By morning a pelt is stretched to dry on a frame.","heroes":["h13"],"parties":["p1"],"loc":"cragtooth_warren","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e1409","day":36,"season":2,"sday":6,"kind":"wild_room","imp":3,"text":"A roost of bats in Cragtooth Warren has joined Ottoline's tune. It is now the best-attended concert the Warren has seen.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","room":"wild_bat_chorus"},{"id":"e1410","day":36,"season":2,"sday":6,"kind":"delve_day","imp":1,"text":"Down in Cragtooth Warren, Red Hammers map two rooms of the first floor, at a steady pace (the dry store, the humming roost).","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_bat_chorus"]}},{"id":"e1451","day":37,"season":2,"sday":7,"kind":"delve_day","imp":1,"text":"Red Hammers work the first floor of Cragtooth Warren without hurrying: two rooms (the tinkers' bench, a chute with chewed footholds).","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1453","day":37,"season":2,"sday":7,"kind":"talent","imp":1,"text":"Ottoline gets a fire going at Cragtooth Warren from a broken chair and some goblin bedding. It burns blue and smells odd but it's warm. Firekeeper all the way, Ottoline insists.","heroes":["h14"],"parties":["p1"],"loc":"cragtooth_warren","skill":"firekeeper"},{"id":"e1468","day":38,"season":2,"sday":8,"kind":"curse","imp":4,"text":"Something is wrong with Red Hammers. Since Bramble picked up the Whispering Crown, nobody trusts anybody, and Bramble won't put it down.","heroes":["h13"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e1485","day":38,"season":2,"sday":8,"kind":"wild_room","imp":3,"text":"Ottoline toasted a kobold's guest-of-honour cheese into Toasted Cheese Trenchers in Cragtooth Warren. The kobolds hold a vigil.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","room":"wild_cheese_wheel"},{"id":"e1486","day":38,"season":2,"sday":8,"kind":"delve_day","imp":1,"text":"Another day under Cragtooth Warren: Red Hammers walk three rooms of the first floor, at a hard pace (the tool locker, the moon of cheese, the sleeping burrows).","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"push","stats":{"rooms":3,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_cheese_wheel"]}},{"id":"e1540","day":39,"season":2,"sday":9,"kind":"wild_room","imp":3,"text":"Bramble won just enough at knucklebones in Cragtooth Warren to be waved through. The kobolds want it known they let him win.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","room":"wild_knucklebones"},{"id":"e1541","day":39,"season":2,"sday":9,"kind":"delve_day","imp":1,"text":"Red Hammers give the first floor of Cragtooth Warren another day, steadily, and two rooms give way (the kobold nursery, the knucklebones circle).","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_knucklebones"]}},{"id":"e1581","day":40,"season":2,"sday":10,"kind":"party_life","imp":3,"text":"Bramble took the measure of the first floor of Cragtooth Warren, found it wanting, and said so. Red Hammers turn back without much of an argument.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","refusal":"h13"},{"id":"e1582","day":40,"season":2,"sday":10,"kind":"delve_done","imp":3,"text":"Red Hammers climb the last ladder after 8 days, and the sitting down happens at the top of it. They inked 50% of the map, made it to the first floor, took 16 rooms off the map's blank side, found the bat roost, the prospectors' diggings, the humming roost and 2 more good rooms, came away with 169 silver between them and turned back when one of them would go no further. Counting every crew that has been down, Cragtooth Warren is partly explored (38%).","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","days":8,"bottom":false,"rooms":["the bat roost","the prospectors' diggings"],"gold":169,"turn":"refused"},{"id":"e1583","day":40,"season":2,"sday":10,"kind":"ability","imp":2,"text":"Bramble waits two hours in the reeds by Cragtooth Warren and comes back with a pelt and enough meat to quiet every stomach.","heroes":["h13"],"parties":["p1"],"loc":"cragtooth_warren","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e1594","day":40,"season":2,"sday":10,"kind":"campfire","imp":3,"text":"Ottoline saves Bramble the good spot by the fire. Again.","heroes":["h14","h13"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e1648","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"Red Hammers set their sights for the season: to finish the season as one of the top three parties.","heroes":["h13","h14"],"parties":["p1"]},{"id":"e1670","day":42,"season":2,"sday":12,"kind":"road","imp":3,"text":"Ottoline turns Lady Perpetua Vane the right way round at last and walks her until the towers come into sight. She calls it 'a pleasant coincidence'.","heroes":["h14","h13"],"parties":["p1"],"road":"carrbridge~ironhaven","traveller":"perpetua","road_rec":"r340"},{"id":"e1694","day":43,"season":2,"sday":13,"kind":"road","imp":3,"text":"Osk audits Bramble's pack at the roadside, item by item, and finds everything in order, to his visible disappointment.","heroes":["h13","h14"],"parties":["p1"],"road":"carrbridge~ironhaven","traveller":"osk","road_rec":"r346"},{"id":"e1707","day":43,"season":2,"sday":13,"kind":"boss_race","imp":3,"text":"The Mimic King's Ghost has visitors coming. Red Hammers and Verdant Edge are both on the way to Cragtooth Warren, and nobody is waiting for the others.","heroes":["h13","h14","h12","h17"],"parties":["p1","p8"],"loc":"cragtooth_warren"},{"id":"e1715","day":43,"season":2,"sday":13,"kind":"ability","imp":2,"text":"Ottoline makes the Ironhaven tavern's doorbell play a jig. The landlord laughs till the tears come, and gives Ottoline the best bed in the house. Ottoline sleeps like a cat in sunshine.","heroes":["h14"],"parties":["p1"],"loc":"ironhaven","skill":"glowing_signboard","sk":"The Glowing Signboard","rule":true},{"id":"e1723","day":44,"season":2,"sday":14,"kind":"curse","imp":5,"text":"Prelate Gaudin takes the Whispering Crown from Bramble's shaking hands, says some very old words over it, and breaks it. 54 silver, and worth every coin.","heroes":["h13"],"parties":["p1"],"loc":"ironhaven"},{"id":"e1745","day":44,"season":2,"sday":14,"kind":"ability","imp":1,"text":"Ottoline swears Bramble hasn't moved since lunch. Then one arrow, one deer, a bundle of pelts, and a camp that sleeps very well.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e1751","day":44,"season":2,"sday":14,"kind":"meet","imp":2,"text":"Red Hammers and Verdant Edge share a fire outside Cragtooth Warren and trade news.","heroes":["h13","h14","h12","h17"],"parties":["p1","p8"],"loc":"cragtooth_warren"},{"id":"e1776","day":45,"season":2,"sday":15,"kind":"delve","imp":1,"text":"Red Hammers descend into Cragtooth Warren, partly explored (38%), map in hand.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e1777","day":45,"season":2,"sday":15,"kind":"wild_room","imp":3,"text":"Bramble pressed the button. Bramble would like everyone to know his one regret is not pressing it sooner.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","room":"wild_the_button"},{"id":"e1778","day":45,"season":2,"sday":15,"kind":"delve_day","imp":1,"text":"Two rooms on the first floor of Cragtooth Warren for Red Hammers today: a hidden room behind the knucklebones circle, the brass button.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":["wild_the_button"]}},{"id":"e1796","day":46,"season":2,"sday":16,"kind":"delve_day","imp":1,"text":"Cragtooth Warren, the first floor: two rooms for Red Hammers, at a steady pace. On the map now: a walled-up room beside the brass button, the stolen-goods bin.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common","common"],"fears":1,"wild":[]}},{"id":"e1816","day":47,"season":2,"sday":17,"kind":"delve_day","imp":1,"text":"A long day on the first floor of Cragtooth Warren. Red Hammers come through one room, without hurrying: the kobold crawl.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":1,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1829","day":47,"season":2,"sday":17,"kind":"gift","imp":2,"text":"By the fire, Ottoline quietly hands Bramble a Deck with Two Queens of Cups. Bramble pockets it like it's treasure.","heroes":["h14","h13"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e1856","day":48,"season":2,"sday":18,"kind":"wild_room","imp":3,"text":"Ottoline sat the Cragtooth hatchlings' pop quiz and topped the class. The teacher is lodging an appeal against their own marks.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","room":"wild_kobold_pop_quiz"},{"id":"e1857","day":48,"season":2,"sday":18,"kind":"delve_day","imp":1,"text":"Red Hammers keep at the first floor of Cragtooth Warren with a look round every corner, two rooms deep in the day: the testing run, the hatchlings' schoolroom.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_kobold_pop_quiz"]}},{"id":"e1858","day":48,"season":2,"sday":18,"kind":"ability","imp":2,"text":"Bramble sits so still at the edge of camp near Cragtooth Warren that a moth lands on his bow. One shot at dusk: supper for all, and a pelt to keep.","heroes":["h13"],"parties":["p1"],"loc":"cragtooth_warren","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e1891","day":49,"season":2,"sday":19,"kind":"party_life","imp":3,"text":"There was a long silence on the first floor, and then Bramble said \"Home\", and Red Hammers turn for the stairs as if it had been their idea.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","refusal":"h13"},{"id":"e1892","day":49,"season":2,"sday":19,"kind":"delve_done","imp":3,"text":"Cragtooth Warren, 5 days on: Red Hammers come up blinking at the daylight. They came across a hidden room behind the knucklebones circle, a walled-up room beside the brass button, the stolen-goods bin and 1 more good room, made it to the first floor, took 7 rooms off the map's blank side, split 199 silver on the way up and turned back when one of them would go no further.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","days":5,"bottom":false,"rooms":["a hidden room behind the knucklebones circle","a walled-up room beside the brass button"],"gold":199,"turn":"refused"},{"id":"e1907","day":49,"season":2,"sday":19,"kind":"campfire","imp":1,"text":"Bramble finds a stone in Ottoline's boot before Ottoline does, and removes it with ceremony.","heroes":["h14","h13"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e1919","day":50,"season":2,"sday":20,"kind":"road","imp":3,"text":"Ottoline pays the pedlar on the road to Ironhaven three copper for a twist of wire on a string. It does look lucky, in the right light.","heroes":["h14","h13"],"parties":["p1"],"road":"cragtooth_warren~ironhaven","road_rec":"r400"},{"id":"e1937","day":50,"season":2,"sday":20,"kind":"ability","imp":2,"text":"The Ironhaven tavern's lantern has been broken for years. Ottoline fixes it with one word. Free supper, free bed, and a toast to their name.","heroes":["h14"],"parties":["p1"],"loc":"ironhaven","skill":"glowing_signboard","sk":"The Glowing Signboard","rule":true},{"id":"e1939","day":50,"season":2,"sday":20,"kind":"campfire","imp":1,"text":"Ottoline patches Bramble's cloak without being asked. Bramble pretends not to notice, then says thanks.","heroes":["h13","h14"],"parties":["p1"],"loc":"ironhaven"},{"id":"e1975","day":51,"season":2,"sday":21,"kind":"meet","imp":2,"text":"Gilded Wall meets Red Hammers on the road between Carrbridge and Ironhaven, and for one evening the talk is all roads, prices and who owes whom.","heroes":["h9","h6","h13","h14"],"parties":["p6","p1"],"loc":"carrbridge"},{"id":"e1976","day":51,"season":2,"sday":21,"kind":"gift","imp":2,"text":"Ottoline gives Bramble a Medal of Baked Crust. \"For luck,\" Ottoline says, and won't explain further.","heroes":["h14","h13"],"parties":["p1"],"loc":"carrbridge"},{"id":"e2001","day":52,"season":2,"sday":22,"kind":"road","imp":3,"text":"Ottoline reads an old map cut into the Four Stones and digs where the cross is. A tin with 8 silver in it has been waiting.","heroes":["h14","h13"],"parties":["p1"],"road":"carrbridge~ironhaven","road_rec":"r420"},{"id":"e2029","day":53,"season":2,"sday":23,"kind":"campfire","imp":2,"text":"Bramble finds Ottoline a treasure at a market stall: a chipped mug with Ottoline's initial on it.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e2047","day":54,"season":2,"sday":24,"kind":"delve","imp":1,"text":"Red Hammers descend into Cragtooth Warren, partly explored (50%), map in hand.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e2048","day":54,"season":2,"sday":24,"kind":"delve_day","imp":1,"text":"Torch by torch through the bottom floor of Cragtooth Warren, Red Hammers make it through two rooms, at full stretch: the sleeping burrows, the black cistern.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"push","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2049","day":54,"season":2,"sday":24,"kind":"ability","imp":2,"text":"Bramble sits so still by the stream at Cragtooth Warren that a heron lands beside him. They fish side by side. The heron gets a trout; Bramble gets a fox, and a pelt.","heroes":["h13"],"parties":["p1"],"loc":"cragtooth_warren","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e2090","day":55,"season":2,"sday":25,"kind":"skim","imp":2,"text":"Ottoline quietly pockets an extra 9 silver while Red Hammers count the rest. Nobody notices.","heroes":["h14"],"parties":["p1"],"loc":"cragtooth_warren","in_fight":"f125"},{"id":"e2091","day":55,"season":2,"sday":25,"kind":"fight","imp":1,"text":"In the crossing of runs on the bottom floor of Cragtooth Warren, Red Hammers cut down 3 Kobolds. Bramble's Patient Shot put the kobold down. Loot: 5 silver each, 5 ore, 1 trinket.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","fight":"f125","foes":["kobold","kobold","kobold"],"where":"in the crossing of runs on the bottom floor of Cragtooth Warren","won":true,"close":false,"shape":"place","reworded":-1},{"id":"e2092","day":55,"season":2,"sday":25,"kind":"wild_room","imp":3,"text":"It was a mimic. It was a hungry mimic. Ottoline, bandaged: 'Still worth it.'","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","room":"wild_not_a_mimic"},{"id":"e2093","day":55,"season":2,"sday":25,"kind":"delve_day","imp":1,"text":"Deeper into the bottom floor of Cragtooth Warren: Red Hammers see three rooms today, one door at a time (the crossing of runs, the chest on the plinth, the chest graveyard).","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":3,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":0,"wild":["wild_not_a_mimic"]}},{"id":"e2094","day":55,"season":2,"sday":25,"kind":"night","imp":2,"text":"A grey dwarf shares Red Hammers' fire on the bottom floor of Cragtooth Warren and swears on his beard there's a room in the Sunken Vault nobody has opened. There isn't much beard left.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e2110","day":55,"season":2,"sday":25,"kind":"talent","imp":2,"text":"Ottoline sews a lucky charm into the lining of Bramble's coat. Bramble only finds it a week later. Every enchanter learns Needle and Thread sooner or later. Not every enchanter learns it like that.","heroes":["h14","h13"],"parties":["p1"],"loc":"cragtooth_warren","skill":"tailor"},{"id":"e2125","day":56,"season":2,"sday":26,"kind":"fight","imp":1,"text":"Red Hammers get the better of a Cave Troll in the troll's long wait on the bottom floor of Cragtooth Warren. Ottoline's Spark Jar finished the fight. Loot: 9 silver each.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","fight":"f127","foes":["cave_troll"],"where":"in the troll's long wait on the bottom floor of Cragtooth Warren","won":true,"close":false,"shape":"plain","reworded":-11},{"id":"e2126","day":56,"season":2,"sday":26,"kind":"wild_room","imp":3,"text":"Ottoline was told by the echo in Cragtooth Warren that things were going very well indeed. Ottoline is looking into having the cave follow them home.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","room":"wild_agreeing_echo"},{"id":"e2127","day":56,"season":2,"sday":26,"kind":"delve_day","imp":1,"text":"Chalk marks on two rooms of the bottom floor of Cragtooth Warren say Red Hammers have been through, at a steady pace (the troll's long wait, the agreeable echo).","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":["wild_agreeing_echo"]}},{"id":"e2133","day":56,"season":2,"sday":26,"kind":"campfire","imp":1,"text":"Ottoline hands Bramble a hot cheap swill at the end of a cold day and asks nothing back.","heroes":["h14","h13"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e2151","day":57,"season":2,"sday":27,"kind":"artifact","imp":5,"text":"Deep in Cragtooth Warren, Bramble finds something with a name: the Ninth Ring. It has clearly been waiting for someone.","heroes":["h13"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e2152","day":57,"season":2,"sday":27,"kind":"delve_day","imp":1,"text":"The bottom floor of Cragtooth Warren, taken steadily: Red Hammers get through two rooms (the stolen-goods bin, the coin-floored room).","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["cosmetic"],"fears":1,"wild":[]}},{"id":"e2153","day":57,"season":2,"sday":27,"kind":"night","imp":1,"text":"Ottoline follows strange lights away from the camp on the bottom floor of Cragtooth Warren, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e2206","day":58,"season":2,"sday":28,"kind":"fight","imp":1,"text":"Red Hammers, in fine spirits lately, beat a Cave Slime in the slime sump on the bottom floor of Cragtooth Warren. Bramble's Patient Shot was the quiet reason it went their way. Loot: 2 slime jelly.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","fight":"f130","foes":["slime"],"where":"in the slime sump on the bottom floor of Cragtooth Warren","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e2207","day":58,"season":2,"sday":28,"kind":"delve_day","imp":1,"text":"Red Hammers spend the day on the bottom floor of Cragtooth Warren, without hurrying, and cover two rooms: the slime sump, the king's tithe-box.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["cosmetic"],"fears":0,"wild":[]}},{"id":"e2208","day":58,"season":2,"sday":28,"kind":"ability","imp":2,"text":"Bramble watches a game trail near Cragtooth Warren from dusk until the moon is up. One arrow, a fat buck, a pelt, and the quietest, happiest camp of the week.","heroes":["h13"],"parties":["p1"],"loc":"cragtooth_warren","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e2243","day":59,"season":2,"sday":29,"kind":"party_life","imp":3,"text":"Bramble got as far as the second floor, sat down, and announced 'This is where I live now.' Nobody argued for long, and Red Hammers turn for home.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","refusal":"h13"},{"id":"e2244","day":59,"season":2,"sday":29,"kind":"delve_done","imp":3,"text":"Red Hammers climb out at last, 6 days older and a good deal dirtier. They got all the way to the bottom, worked through 11 rooms, turned up the black cistern, the chest on the plinth, the chest graveyard and 4 more good rooms, put 76% of it on paper, came away with 201 silver between them and turned back when one of them would go no further. Cragtooth Warren now stands mostly explored (76%), every crew's chalk marks counted.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","days":6,"bottom":true,"rooms":["the black cistern","the chest on the plinth"],"gold":201,"turn":"refused"},{"id":"e2261","day":59,"season":2,"sday":29,"kind":"music","imp":3,"text":"A crew anthem is born: \"Letters in the Fire\". Red Hammers sang it under the stars last night, and by the last chorus it was theirs.","heroes":["h13","h14"],"parties":["p1"],"loc":"cragtooth_warren","anthem":"letters_in_the_fire","night":"n142"},{"id":"e2284","day":60,"season":2,"sday":30,"kind":"talent","imp":1,"text":"An Ironhaven fisherman offers Bramble a job. He is better at waiting than anyone on the pier.","heroes":["h13"],"parties":["p1"],"loc":"ironhaven","skill":"still_as_a_heron","wx":"heat"},{"id":"e2285","day":60,"season":2,"sday":30,"kind":"ability","imp":2,"text":"An Ironhaven tavern's painted sign is so faded nobody knows its name. Ottoline brings back 'The Laughing Trout' in gold light. Free bed, free breakfast, and a fine night's sleep.","heroes":["h14"],"parties":["p1"],"loc":"ironhaven","skill":"glowing_signboard","sk":"The Glowing Signboard","rule":true,"wx":"heat"},{"id":"e2286","day":60,"season":2,"sday":30,"kind":"campfire","imp":2,"text":"Bramble and Ottoline trade war stories at The Gilded Flagon until the fire burns down.","heroes":["h13","h14"],"parties":["p1"],"loc":"ironhaven","wx":"heat"},{"id":"e2297","day":60,"season":2,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and Red Hammers came up short: finish the season as one of the top three parties (finished 6th).","heroes":["h13","h14"],"parties":["p1"]},{"id":"e2407","day":63,"season":3,"sday":3,"kind":"ambush","imp":3,"text":"With Bramble hitting hardest, Red Hammers see off a Giant Rat and a Skeleton at their camp in the Ashveil Crypts, in the middle of the night. Look past the blows: Bramble's Patient Shot was the difference. Ottoline led the singing on the way back. Badly. Everyone joined in. Loot: 1 fang, a rat haunch, 2 bones.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f138","foes":["giant_rat","skeleton"],"where":"at their camp in The Ashveil Crypts, in the middle of the night","won":true,"close":false,"shape":"hero","reworded":-30},{"id":"e2442","day":64,"season":3,"sday":4,"kind":"delve","imp":1,"text":"Red Hammers descend into the Ashveil Crypts, mostly unexplored (17%).","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e2443","day":64,"season":3,"sday":4,"kind":"delve_day","imp":1,"text":"The embalming room, the gravediggers' bunks: the day's work on the first floor of the Ashveil Crypts for Red Hammers, taken one door at a time.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"rain"},{"id":"e2458","day":65,"season":3,"sday":5,"kind":"fight","imp":1,"text":"It's a Wraith against Red Hammers in the widows' walk on the first floor of the Ashveil Crypts, and it isn't close. Bramble's Patient Shot kicked in when it counted. Loot: 2 ectoplasm, 2 wraith-frost.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f142","foes":["wraith"],"where":"in the widows' walk on the first floor of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-14},{"id":"e2459","day":65,"season":3,"sday":5,"kind":"fight","imp":3,"text":"In the coffin racks on the first floor of the Ashveil Crypts, 2 Risen Dead and a Skeleton get in Red Hammers' way, briefly. It was even until Bramble's Headshot. Then it wasn't. Without Ottoline's Spellsong, this goes differently. Loot: 4 bones, 2 grave dust, 2 remains.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f143","foes":["skeleton","zombie","zombie"],"where":"in the coffin racks on the first floor of the Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-17},{"id":"e2460","day":65,"season":3,"sday":5,"kind":"delve_day","imp":1,"text":"Red Hammers work the first floor of the Ashveil Crypts slowly, chalking every door: two rooms (the widows' walk, the coffin racks).","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2506","day":66,"season":3,"sday":6,"kind":"fight","imp":3,"text":"Red Hammers meet 3 Skeleton Archers in the ossuary on the first floor of the Ashveil Crypts and cut them down. Ottoline wove Spellsong over the others and they felt it. Patient Shot came over Bramble at the right moment, as it does. Loot: 9 bones, 4 crypt-caps.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f151","foes":["skeleton_archer","skeleton_archer","skeleton_archer"],"where":"in the ossuary on the first floor of the Ashveil Crypts","won":true,"close":false,"shape":"plain","reworded":-14},{"id":"e2507","day":66,"season":3,"sday":6,"kind":"delve_day","imp":1,"text":"Another day under the Ashveil Crypts: Red Hammers walk three rooms of the first floor, without stopping for side rooms (the ossuary, the wake cellar, a spiral stair behind the ossuary screen).","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":3,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2533","day":67,"season":3,"sday":7,"kind":"delve_day","imp":1,"text":"Red Hammers push on through the second floor of the Ashveil Crypts at speed. Two rooms by nightfall: the grave-goods store, the mason's yard.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e2569","day":68,"season":3,"sday":8,"kind":"delve_day","imp":1,"text":"Three rooms on the second floor of the Ashveil Crypts for Red Hammers today: the cold room, the chapel of the weeping saint, the chapel of statues.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":3,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2592","day":69,"season":3,"sday":9,"kind":"delve_day","imp":1,"text":"The map of the Ashveil Crypts grows by two rooms of the second floor, walked at a steady pace by Red Hammers: the candle vault, the family archive.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2593","day":69,"season":3,"sday":9,"kind":"talent","imp":1,"text":"Bramble strings cans round camp at dusk. At midnight a hedgehog sets off every one, and the whole crew is up and armed.","heroes":["h13"],"parties":["p1"],"loc":"ashveil_crypts","skill":"tin_can_line"},{"id":"e2627","day":70,"season":3,"sday":10,"kind":"party_life","imp":3,"text":"Bramble began counting steps on the second floor and could not stop. By the time the count reached sixty, Red Hammers turn for the way out.","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","refusal":"h13"},{"id":"e2628","day":70,"season":3,"sday":10,"kind":"delve_done","imp":3,"text":"The Ashveil Crypts, 7 days on: Red Hammers come up blinking at the daylight. They got down to the second floor, turned up the grave-goods store, the cold room and the chapel of statues, worked through 14 rooms, put 52% of it on paper, split 73 silver on the way up and turned back when one of them would go no further. Add up every party's sketches and the Ashveil Crypts comes out partly explored (41%).","heroes":["h13","h14"],"parties":["p1"],"loc":"ashveil_crypts","days":7,"bottom":false,"rooms":["the grave-goods store","the cold room"],"gold":73,"turn":"refused"},{"id":"e2670","day":71,"season":3,"sday":11,"kind":"road","imp":3,"text":"Captain Dorrit Salt swears to Ottoline she has heard a rumour of something dreadful near Thornmere Ruins, and a pub that serves the best rum on land.","heroes":["h14","h13"],"parties":["p1"],"road":"ashfen~ashveil_crypts","traveller":"salt","road_rec":"r562"},{"id":"e2681","day":71,"season":3,"sday":11,"kind":"talent","imp":1,"text":"Ottoline makes the Ashfen tavern's candles burn twice as long. The landlord sends over pie. Ottoline puts it down to The Glowing Signboard.","heroes":["h14"],"parties":["p1"],"loc":"ashfen","skill":"glowing_signboard"},{"id":"e2684","day":71,"season":3,"sday":11,"kind":"talent","imp":1,"text":"Bramble trades a jar of wild honey to an Ashfen healer for a pouch of dried herbs. Honey Finder: a ranger's patience, mostly.","heroes":["h13"],"parties":["p1"],"loc":"ashfen","skill":"honey_finder"},{"id":"e2685","day":71,"season":3,"sday":11,"kind":"ability","imp":2,"text":"Ottoline charms the Ashfen inn's weathervane so it glows when rain is coming. The landlord gives them the warm room above the kitchen. Ottoline wakes rested and mended.","heroes":["h14"],"parties":["p1"],"loc":"ashfen","skill":"glowing_signboard","sk":"The Glowing Signboard","rule":true},{"id":"e2697","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, Red Hammers settle on a goal: to earn 1,550 silver between them before the season ends.","heroes":["h13","h14"],"parties":["p1"]},{"id":"e2723","day":72,"season":3,"sday":12,"kind":"road","imp":4,"text":"A giant lies asleep across the road to Bleakmarsh, a hill with a beard. Every traveller queues to climb over the arm. Ottoline goes last and sits on a finger.","heroes":["h14","h13"],"parties":["p1"],"road":"ashfen~bleakmarsh","road_rec":"r575"},{"id":"e2724","day":72,"season":3,"sday":12,"kind":"ability","imp":1,"text":"A hare sits up in the grass at Bleakmarsh, looks right at Bramble, and decides Bramble is a stump. Supper. By morning a pelt is stretched to dry on a frame.","heroes":["h13"],"parties":["p1"],"loc":"bleakmarsh","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e2735","day":72,"season":3,"sday":12,"kind":"meet","imp":1,"text":"Red Hammers and The Scarlet Gallopers share a fire in Bleakmarsh. Ottoline shares a bad map.","heroes":["h13","h14","h4","h15","h5"],"parties":["p1","p5"],"loc":"bleakmarsh"},{"id":"e2748","day":73,"season":3,"sday":13,"kind":"night","imp":1,"text":"A tinker trades Red Hammers' camp in Thornmere Ruins a kettle for a story, then tells one back: something under Goblin Camp is still awake.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e2789","day":74,"season":3,"sday":14,"kind":"delve","imp":1,"text":"Red Hammers descend into Thornmere Ruins, partly explored (38%).","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e2790","day":74,"season":3,"sday":14,"kind":"delve_day","imp":1,"text":"Down in Thornmere Ruins, Red Hammers map eight rooms of the first floor, at a hard pace (the reed beds, the smugglers' dry stair, the porters' lodge and 5 more).","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":8,"empty":8,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"storm"},{"id":"e2848","day":75,"season":3,"sday":15,"kind":"delve_day","imp":1,"text":"It's the first floor of Thornmere Ruins today, and Red Hammers work through it one door at a time: six rooms (the drowned nave, the flooded side aisle, the wayside cross and 3 more).","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":6,"empty":6,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"storm"},{"id":"e2849","day":75,"season":3,"sday":15,"kind":"talent","imp":2,"text":"Bramble brews something green and bitter for Ottoline's cough. Ottoline hates it. The cough's gone by morning.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","skill":"herbalism","wx":"storm"},{"id":"e2850","day":75,"season":3,"sday":15,"kind":"night","imp":1,"text":"Bramble's ghost story on the first floor of Thornmere Ruins goes on too long and never really ends. Ottoline lies awake waiting for the ending.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e2893","day":76,"season":3,"sday":16,"kind":"party_life","imp":3,"text":"Bramble proposed a vote on the first floor. It was one to none, and the one was loud enough that Red Hammers turn for home.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","refusal":"h13","wx":"storm"},{"id":"e2894","day":76,"season":3,"sday":16,"kind":"delve_done","imp":1,"text":"Red Hammers come out into the light after 3 days with the dark still in every seam. They got no further than the entrance, inked 23% of the map and turned back when one of them would go no further. Between every crew so far, Thornmere Ruins is partly explored (38%).","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","days":3,"bottom":false,"rooms":[],"gold":0,"turn":"refused","wx":"storm"},{"id":"e2895","day":76,"season":3,"sday":16,"kind":"night","imp":1,"text":"Bramble follows strange lights away from the camp outside Thornmere Ruins, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e2899","day":76,"season":3,"sday":16,"kind":"meet","imp":2,"text":"Red Hammers and Verdant Edge share a fire outside Thornmere Ruins. Nobody draws steel, which counts as a good meeting these days.","heroes":["h13","h14","h12","h17"],"parties":["p1","p8"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e2905","day":76,"season":3,"sday":16,"kind":"campfire","imp":1,"text":"Bramble and Ottoline split the washing-up by a system so complicated that nobody ends up doing any.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e2921","day":77,"season":3,"sday":17,"kind":"ability","imp":2,"text":"Bramble waits two hours in the reeds by Bleakmarsh and comes back with a pelt and enough meat to quiet every stomach.","heroes":["h13"],"parties":["p1"],"loc":"bleakmarsh","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true,"wx":"storm"},{"id":"e2924","day":77,"season":3,"sday":17,"kind":"bond","imp":3,"text":"Red Hammers and The Sunlit Almanac are rivals now, starting with Ottoline and Barnaby.","heroes":["h14","h19"],"parties":["p1","p4"],"bond":"rivals"},{"id":"e2925","day":77,"season":3,"sday":17,"kind":"meet","imp":1,"text":"Red Hammers and The Sunlit Almanac share a fire in Bleakmarsh. Ottoline shares a flask.","heroes":["h13","h14","h8","h20","h18","h19"],"parties":["p1","p4"],"loc":"bleakmarsh","wx":"storm"},{"id":"e3001","day":79,"season":3,"sday":19,"kind":"ability","imp":2,"text":"Ottoline makes the Ashfen tavern's sign glow a lovely gold. The landlord gives them the best room free, and Ottoline sleeps like a cat.","heroes":["h14"],"parties":["p1"],"loc":"ashfen","skill":"glowing_signboard","sk":"The Glowing Signboard","rule":true,"wx":"storm"},{"id":"e3032","day":80,"season":3,"sday":20,"kind":"map_bought","imp":2,"text":"Red Hammers buy a map of Thornmere Ruins in Ashfen for 33 silver, drawn by Rook. The place is partly explored (51%).","heroes":["h13","h14","h15"],"parties":["p1"],"loc":"ashfen","wx":"fog"},{"id":"e3033","day":80,"season":3,"sday":20,"kind":"ambush","imp":2,"text":"In thick fog, Red Hammers dispatch a Will-o'-Wisp and Risen Dead at their camp in Bleakmarsh, in the middle of the night. Spark Jar, from Ottoline, was the last thing the risen dead saw. Patient Shot did more for this fight than the scoreboard shows. That was Bramble. Loot: 2 bottled wisplight, 2 wisp sugar, 3 grave dust.","heroes":["h13","h14"],"parties":["p1"],"loc":"bleakmarsh","fight":"f173","foes":["wisp","zombie"],"where":"at their camp in Bleakmarsh, in the middle of the night","won":true,"close":false,"shape":"weather","reworded":-14,"wx":"fog"},{"id":"e3040","day":80,"season":3,"sday":20,"kind":"talent","imp":1,"text":"Bramble pulls a handful of yarrow from a field edge and stuffs it in a pouch. 'For later. You'll see.'","heroes":["h13"],"parties":["p1"],"loc":"bleakmarsh","skill":"herbalism","wx":"fog"},{"id":"e3091","day":81,"season":3,"sday":21,"kind":"ledger","imp":2,"text":"Counters and coin this week: 17 sales, 870 silver changing hands. Biggest haul: Duren, 103 silver in Frosthold. Back up from the deep: Red Hammers (3 days in Thornmere Ruins), Gilded Wall (2 days in Emberdeep), The Oath of Frosthold (1 day in Frostspire).","heroes":["h3","h13","h9"],"parties":["p1","p6","p7"]},{"id":"e3110","day":82,"season":3,"sday":22,"kind":"delve","imp":1,"text":"Red Hammers descend into Thornmere Ruins, partly explored (60%), map in hand.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e3111","day":82,"season":3,"sday":22,"kind":"delve_day","imp":1,"text":"By lamplight on the second floor of Thornmere Ruins, Red Hammers clear the way through five rooms, at a steady pace: The Lantern That Waits, the reliquary niche, the curtain of hair and 2 more.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":5,"empty":5,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e3117","day":82,"season":3,"sday":22,"kind":"map_shared","imp":1,"text":"Red Hammers charge The Vigil of Carrbridge 6 silver to copy the map of the Ashveil Crypts. It's a fair price for a good map.","heroes":["h13","h14","h10","h1"],"parties":["p1","p2"],"loc":"thornmere_ruins","dungeon":"ashveil_crypts","price":6,"wx":"fog"},{"id":"e3118","day":82,"season":3,"sday":22,"kind":"meet","imp":1,"text":"Red Hammers and The Vigil of Carrbridge share a fire in Thornmere Ruins. There is a short argument about the best road to Thornwall.","heroes":["h13","h14","h10","h1"],"parties":["p1","p2"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e3126","day":82,"season":3,"sday":22,"kind":"campfire","imp":2,"text":"Bramble and Ottoline share the last pickled onion by cutting it exactly in half, with witnesses.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e3135","day":83,"season":3,"sday":23,"kind":"party_life","imp":3,"text":"Bramble stood in the doorway on the second floor for a long time, shook a head, and walked out. Red Hammers turn after Bramble, one by one.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","refusal":"h13"},{"id":"e3136","day":83,"season":3,"sday":23,"kind":"delve_done","imp":1,"text":"Thornmere Ruins is behind Red Hammers now: 2 days down there, and the sky looks enormous. They turned round at the first door, inked 51% of the map, split 6 silver on the way up and turned back when one of them would go no further. Counting every crew that has been down, Thornmere Ruins is partly explored (61%).","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","days":2,"bottom":false,"rooms":[],"gold":6,"turn":"refused"},{"id":"e3212","day":85,"season":3,"sday":25,"kind":"road","imp":3,"text":"Ottoline helps push a menagerie wagon out of a rut on the road to Carrbridge, and the keeper shows them the star of the show: a small, grumpy, very real wyvern.","heroes":["h14","h13"],"parties":["p1"],"road":"bleakmarsh~carrbridge","road_rec":"r680"},{"id":"e3249","day":86,"season":3,"sday":26,"kind":"ambush","imp":2,"text":"A Bog Crawler makes the mistake of going for Red Hammers on the road to Bleakmarsh. Bramble put Piercing Arrow into the bog crawler to end it, and lowered the bow. Ask the others what won it: Bramble's Patient Shot. Ottoline kept the bleeding to a minimum. Loot: 3 chitin, 2 bog crawler claws.","heroes":["h13","h14"],"parties":["p1"],"loc":"bleakmarsh","fight":"f183","foes":["bog_crawler"],"where":"on the road to Bleakmarsh","won":true,"close":false,"shape":"foe","reworded":-22},{"id":"e3250","day":86,"season":3,"sday":26,"kind":"talent","imp":1,"text":"Bramble sets the crew a riddle at dinner. Ottoline gets it on the third day.","heroes":["h13","h14"],"parties":["p1"],"loc":"bleakmarsh","skill":"riddler"},{"id":"e3257","day":86,"season":3,"sday":26,"kind":"sniped","imp":3,"text":"On the road to Thornmere Ruins, Red Hammers hear that The Vigil of Carrbridge killed Mother Thornmere's Brood today. Red Hammers go on anyway: the place is still mostly explored (68%), and there's more down there than one boss.","heroes":["h13","h14","h10","h1"],"parties":["p1","p2"],"loc":"thornmere_ruins","snipers":["h10","h1"],"where":"road","boss":"Mother Thornmere's Brood","in_fight":"f184"},{"id":"e3289","day":87,"season":3,"sday":27,"kind":"ambush","imp":2,"text":"With Bramble taking the worst of it, Red Hammers handle 2 Bog Crawlers and a Giant Spider on the road to Thornmere Ruins. Bramble ended it the plain way: Ride Past, and the bog crawler on the ground. Spellsong did more for this fight than the scoreboard shows. That was Ottoline. Loot: 5 chitin, a giant spider leg, 2 bog crawler claws.","heroes":["h13","h14"],"parties":["p1"],"loc":"bleakmarsh","fight":"f189","foes":["bog_crawler","giant_spider","bog_crawler"],"where":"on the road to Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-37},{"id":"e3290","day":87,"season":3,"sday":27,"kind":"ability","imp":2,"text":"Bramble sits so still at the edge of camp near Thornmere Ruins that a moth lands on their bow. One shot at dusk: supper for all, and a pelt to keep.","heroes":["h13"],"parties":["p1"],"loc":"thornmere_ruins","skill":"still_as_a_heron","sk":"Still as a Heron","rule":true},{"id":"e3301","day":87,"season":3,"sday":27,"kind":"campfire","imp":1,"text":"After the fight, Bramble and Ottoline sit back to back on a rock and don't say anything for a long time.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e3316","day":88,"season":3,"sday":28,"kind":"delve","imp":1,"text":"Red Hammers descend into Thornmere Ruins, mostly explored (70%), map in hand.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e3317","day":88,"season":3,"sday":28,"kind":"fight","imp":1,"text":"Red Hammers, in fine spirits lately, beat a Will-o'-Wisp and a Bog Crawler in the gatehouse yard on the first floor of Thornmere Ruins. Piercing Arrow, from Bramble, was the last thing the will-o'-wisp saw. Bramble's Patient Shot picked its moment well. Loot: 2 bottled wisplight, 2 wisp sugar.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f190","foes":["wisp","bog_crawler"],"where":"in the gatehouse yard on the first floor of Thornmere Ruins","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"rain"},{"id":"e3318","day":88,"season":3,"sday":28,"kind":"delve_day","imp":1,"text":"Red Hammers tally up the first floor of Thornmere Ruins at nightfall: two rooms, taken steadily, and the names go in the book (the gatehouse yard, the scriptorium).","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"rain"},{"id":"e3355","day":88,"season":3,"sday":28,"kind":"ledger","imp":2,"text":"MARKET WEEK: 14 hauls sold across the realm, 965 silver all told. Biggest haul: Juniper, 151 silver in Ashfen. Back up from the deep: Red Hammers (2 days in Thornmere Ruins).","heroes":["h10","h13"],"parties":["p1"]},{"id":"e3366","day":89,"season":3,"sday":29,"kind":"wild_room","imp":3,"text":"Bramble caught a wisp in a game of tag in Thornmere Ruins and the whole hall of them lay down, as pleased as lights can be. The wisp is said to be 'it.'","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","room":"wild_wisp_tag","wx":"rain"},{"id":"e3367","day":89,"season":3,"sday":29,"kind":"delve_day","imp":1,"text":"Red Hammers push on through the first floor of Thornmere Ruins one door at a time. Two rooms by nightfall: the buttery, the wisps' game of tag.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common","cosmetic"],"fears":0,"wild":["wild_wisp_tag"]},"wx":"rain"},{"id":"e3386","day":89,"season":3,"sday":29,"kind":"talent","imp":2,"text":"Bramble watches the treeline for an hour without moving. Ottoline checks he is still breathing. Still as a Heron, the guild calls it.","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","skill":"still_as_a_heron","wx":"rain"},{"id":"e3396","day":90,"season":3,"sday":30,"kind":"delve_day","imp":1,"text":"Red Hammers work the second floor of Thornmere Ruins without hurrying: two rooms (the bell tower, the cloister garth).","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e3418","day":90,"season":3,"sday":30,"kind":"campfire","imp":2,"text":"Ottoline and Bramble start a running tally of who saved whom. It is currently tied, and disputed.","heroes":["h14","h13"],"parties":["p1"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e3426","day":90,"season":3,"sday":30,"kind":"delve_done","imp":3,"text":"After 3 days underground, Red Hammers climb back into the open air, gulping it down like water. They found the buttery and the wisps' game of tag, got down to the second floor, cleared 6 rooms, mapped 59% of it and split 85 silver on the way up. No boss, but the place paid. Thornmere Ruins, all crews together: mostly explored (80%).","heroes":["h13","h14"],"parties":["p1"],"loc":"thornmere_ruins","days":3,"bottom":false,"rooms":["the buttery","the wisps' game of tag"],"gold":85,"wx":"rain"},{"id":"e3432","day":90,"season":3,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and Red Hammers came up short: earn 1,550 silver between them before the season ends (268 of 1,550 silver).","heroes":["h13","h14"],"parties":["p1"]},{"id":"e3450","day":90,"season":3,"sday":30,"kind":"vow_broken","imp":3,"text":"VOW BROKEN. Red Hammers, The Oath of Frosthold, Ottoline and Rook swore to die rich, and the age ends with the purse short. Comfortable, at best.","heroes":["h14","h15"],"parties":["p1","p7"]}],"roles":{"h14":"Purse-keeper","h13":"Leader · Blade"},"quest":{"what":"Delve","where":"Thornmere Ruins","why":"chasing a rumour: about 50 silver a day each, risk slight; the season goal: to earn 1,550 silver between them before the season ends","floor":1,"floors":3},"tactics":{"front":[],"back":["h13","h14"],"plan":"Ottoline casts from behind; Bramble picks off whatever gets close.","traits":{"boldness":-0.12,"risk":0.34,"greed":0.49,"sociability":0.55,"honor":-0.26,"curiosity":-0.31,"temper":-0.32,"loyalty":0.11},"mix":"1 bow, 1 caster","notes":["Nobody wants the front row. Whoever's nearest takes the hits.","No healer: every wound comes home with them."],"style":["reckless","silver-hungry","mixed"],"skills":[{"label":"Damage","skills":[{"hero":"h14","id":"spark_jar","name":"Spark Jar","desc":"A jar of captured sparks, uncorked in the wrong direction.","tags":["craft"],"rank":3,"uses":6},{"hero":"h13","id":"headshot","name":"Headshot","desc":"Between the eyes.","tags":["crit"],"rank":1,"uses":4},{"hero":"h13","id":"piercing_arrow","name":"Piercing Arrow","desc":"Through armor, through the next guy.","tags":["crit"],"rank":1,"uses":3},{"hero":"h14","id":"charged_trinket","name":"Charged Trinket","desc":"Throws something that was a teapot.","tags":["craft"],"rank":1,"uses":2},{"hero":"h14","id":"alchemists_fire","name":"Alchemist's Fire","desc":"A clay jar with strong opinions.","tags":["craft","fire"],"rank":1,"uses":2},{"hero":"h13","id":"ride_past","name":"Ride Past","desc":"Gallops round the end of the line and strikes whoever was hiding behind it.","tags":["ride"],"rank":1,"uses":1}]},{"label":"Defence","skills":[{"hero":"h14","id":"spellsong","name":"Spellsong","desc":"Hums a tune that makes swords sharper.","tags":["music","arcane"],"rank":2,"uses":9}]},{"label":"Tricks","skills":[{"hero":"h13","id":"patient_shot","name":"Patient Shot","desc":"Has had the shot lined up since breakfast.","tags":["crit"],"rank":2,"uses":15}]},{"label":"Always on","skills":[{"hero":"h13","id":"lucky","name":"Lucky","desc":"Things just work out.","tags":["crit"],"rank":3,"uses":0},{"hero":"h13","id":"precision","name":"Precision","desc":"Finds the gap every time.","tags":["crit"],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h13","id":"tin_can_line","name":"Tin-Can Line","desc":"Cans on a string round the camp. Nothing sneaks up. Nobody sleeps.","tags":["nature","craft"],"rank":1,"uses":0},{"hero":"h13","id":"herbalism","name":"Herbalism","desc":"Knows every useful leaf.","tags":["nature","heal"],"rank":1,"uses":0},{"hero":"h13","id":"fencing_lessons","name":"Fencing Lessons","desc":"Teaches the basics. Charges for the advanced.","tags":["crit"],"rank":1,"uses":0},{"hero":"h13","id":"honey_finder","name":"Honey Finder","desc":"Follows the bees. Comes back sticky.","tags":[],"rank":1,"uses":0},{"hero":"h13","id":"trick_shot","name":"Trick Shot","desc":"Shoots the apple off your head. Asks first.","tags":["crit"],"rank":1,"uses":0},{"hero":"h13","id":"gambler","name":"Gambler","desc":"Dice nights are profitable. Usually.","tags":[],"rank":1,"uses":0},{"hero":"h13","id":"riddler","name":"Riddle Solver","desc":"Answers the door's riddle before it finishes asking.","tags":["lore"],"rank":1,"uses":0},{"hero":"h14","id":"busker","name":"Busker","desc":"Hat on the ground, song in the air.","tags":["music","travel"],"rank":2,"uses":0},{"hero":"h14","id":"enchant_gear","name":"Enchant Gear","desc":"Weapons glow a bit after a night in their tent.","tags":["craft"],"rank":1,"uses":0},{"hero":"h14","id":"firekeeper","name":"Firekeeper","desc":"Lights a fire in a rainstorm, with wet wood, every time.","tags":[],"rank":1,"uses":0},{"hero":"h14","id":"smith_hands","name":"Smith's Hands","desc":"Fixes and upgrades their own gear.","tags":["craft"],"rank":2,"uses":0},{"hero":"h14","id":"carpenter","name":"Carpentry","desc":"Measures twice, cuts once, builds a bench.","tags":["craft"],"rank":1,"uses":0},{"hero":"h14","id":"tailor","name":"Needle and Thread","desc":"Mends cloaks, patches tents, takes in trousers.","tags":["craft"],"rank":1,"uses":0},{"hero":"h14","id":"tinkers_mending","name":"Tinker's Mending","desc":"Fixes gear overnight with a word and a hammer.","tags":["craft"],"rank":2,"uses":0}]}],"share":[{"hero":"h13","dmg":2053,"healed":0,"taken":105,"kills":16,"row":"back"},{"hero":"h14","dmg":204,"healed":0,"taken":18,"kills":1,"row":"back"}],"ground":{"name":"The Ashveil Crypts","fights":5}},"trophies":[]};